// Deterministic local HTML, not a recording or live YouTube DOM.
const titles = ['A quiet morning in the mountains', 'Build a better creative routine', 'Inside a beautifully simple workspace', 'The science of deep focus', 'A weekend away from everything', 'Small ideas that change your day'];
function image(i) {
  const colors = ['#355849','#ad673d','#3d5778','#76506e','#426471','#736446'];
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="640" height="360"><rect width="640" height="360" fill="${colors[i%6]}"/><circle cx="490" cy="90" r="65" fill="#efc993" opacity=".8"/><path d="M0 360L190 90L360 320L460 190L640 360" fill="#14262c" opacity=".7"/><text x="30" y="315" font-family="Arial" font-weight="bold" font-size="35" fill="white">${['SLOW LIVING','MAKE SOMETHING','THE STUDIO','FIND YOUR FOCUS','OUTSIDE','LESS, BUT BETTER'][i%6]}</text></svg>`;
  return 'data:image/svg+xml;base64,' + Buffer.from(svg).toString('base64');
}
function card(i, compact=false, modern=false) {
  const title = titles[i%6], outer=compact?'ytd-compact-video-renderer':'ytd-rich-item-renderer';
  if(modern) return `<yt-lockup-view-model class="card modern" data-test-card="${i}"><a class="yt-lockup-view-model__content-image" href="/watch?v=fixture${i}"><yt-thumbnail-view-model><img src="${image(i)}" alt="${title}"><span class="duration">12:48</span></yt-thumbnail-view-model></a><div class="meta yt-lockup-view-model__metadata ytLockupViewModelMetadata"><img class="channel-avatar" src="${image(i+1)}" alt="Everyday studio avatar"><h3 class="yt-lockup-metadata-view-model__heading-reset"><a class="yt-lockup-metadata-view-model__title" href="/watch?v=fixture${i}">${title}</a></h3><p class="channel-name">Everyday studio</p><p class="video-stats">42K views · 3 days ago <span class="metadata-badge">4K</span></p></div></yt-lockup-view-model>`;
  return `<${outer} class="card ${compact?'compact':''}" data-test-card="${i}"><ytd-rich-grid-media><ytd-thumbnail class="legacy-thumbnail"><a id="thumbnail" class="yt-simple-endpoint" href="/watch?v=fixture${i}"><yt-image><img src="${image(i)}" alt="${title}"></yt-image><span class="duration">18:24</span></a></ytd-thumbnail><div id="details" class="meta details text-wrapper"><img class="channel-avatar" src="${image(i+1)}" alt="Everyday studio avatar"><h3><a id="video-title" href="/watch?v=fixture${i}">${title}</a></h3><p class="channel-name">Everyday studio</p><p class="video-stats">128K views · 2 days ago <span class="metadata-badge">HD</span></p></div></ytd-rich-grid-media></${outer}>`;
}
function html(watch=false) { return `<!doctype html><html dark><head><meta charset="utf-8"><title>YouTube layout fixture</title><style>
*{box-sizing:border-box}body{margin:0;background:#0f0f0f;color:#f1f1f1;font:14px Arial,sans-serif}a{color:inherit;text-decoration:none}header{height:64px;display:flex;align-items:center;gap:28px;padding:0 30px;background:#0f0f0f}header strong{font-size:24px;letter-spacing:-1px}.logo{display:inline-block;background:#ff0033;border-radius:7px;padding:2px 9px;font-size:18px;margin-right:4px}.search{margin:auto;width:520px;border:1px solid #393939;border-radius:30px;padding:12px 20px;color:#999}aside.nav{position:fixed;width:200px;padding:18px}.nav div{padding:15px;border-radius:10px}.nav div:first-child{background:#272727}.fixture-label{font-size:10px;color:#aaa;border:1px solid #444;padding:6px;border-radius:5px;letter-spacing:1px}.home{margin:12px 32px 0 225px}.chips{display:flex;gap:12px;margin:15px 0 26px}.chips span{padding:9px 13px;background:#282828;border-radius:8px}.chips span:first-child{background:#eee;color:#111}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:32px 18px}.card,ytd-rich-grid-media,yt-image,yt-thumbnail-view-model{display:block;min-width:0}#thumbnail,.yt-lockup-view-model__content-image{display:block;position:relative;aspect-ratio:16/9;background:#222;border-radius:12px;overflow:hidden}img{display:block;width:100%;height:100%;object-fit:cover}.duration{position:absolute;right:8px;bottom:8px;background:#000c;border-radius:3px;padding:3px;font-size:12px}.legacy-thumbnail{display:block;position:relative;min-width:0}.legacy-thumbnail::before{content:"";display:block;padding-top:56.25%}.legacy-thumbnail>a#thumbnail{position:absolute;inset:0;width:100%;height:100%;aspect-ratio:auto}.meta{padding:11px 2px;display:flow-root}.channel-avatar{float:left;width:28px;height:28px;border-radius:50%;margin:2px 8px 20px 0;object-fit:cover}.metadata-badge{padding:1px 3px;border-radius:2px;background:#303030;font-size:9px;color:#bbb}h3{font-size:15px;line-height:21px;margin:0 0 6px}p{color:#aaa;font-size:12px;line-height:19px;margin:0}.watch{display:grid;grid-template-columns:minmax(0,1fr) 370px;gap:26px;margin:22px 38px}.player{aspect-ratio:16/9;background:radial-gradient(ellipse at 65% 25%,#687475,#23323a 45%,#0c151b);border-radius:12px;position:relative;display:flex;align-items:center;justify-content:center;color:#d5dedc}.player .scene{font:italic 30px Georgia;color:#dce5de}.controls{position:absolute;bottom:0;left:0;right:0;padding:18px;background:linear-gradient(transparent,#000);font-size:16px}h1{font-size:21px;margin:19px 0}.channel{display:flex;gap:14px;align-items:center;padding:0 0 22px}.avatar{width:42px;height:42px;border-radius:50%;background:#4a6057}.subscribe{background:#eee;color:#111;border-radius:30px;padding:10px 16px;margin-left:10px}.description{background:#272727;border-radius:12px;padding:18px;line-height:22px}.recommendations{display:grid;gap:13px;align-content:start}.compact ytd-rich-grid-media,.recommendations .modern{display:grid;grid-template-columns:165px 1fr;gap:10px}.compact .meta,.recommendations .modern .meta{padding:0}.compact h3,.recommendations .modern h3{font-size:13px;line-height:18px}.shorts{margin-top:38px}.short-grid{display:flex;gap:18px}.short-grid ytd-reel-item-renderer{display:block;width:180px}.short-grid #thumbnail{aspect-ratio:9/14}.short-grid h3{margin-top:12px}
</style></head><body><header><span>☰</span><strong><span class="logo">▶</span>YouTube</strong><div class="search">Search</div><span class="fixture-label">LOCAL QA FIXTURE · NOT LIVE YOUTUBE</span><span>●</span></header>${watch?`<main class="watch"><section><div id="movie_player" class="html5-video-player player"><span class="scene">A little room to think.</span><div class="controls">▶ ━━━━━━━━━━━━━━━━ 02:34 / 18:24　　 ⚙　□</div></div><ytd-watch-metadata><h1><yt-formatted-string id="watched-title">A quiet morning in the mountains — full film</yt-formatted-string></h1></ytd-watch-metadata><div id="watched-channel" class="channel"><span class="avatar"></span><b>Everyday studio<br><small>284K subscribers</small></b><span class="subscribe">Subscribe</span><span style="margin-left:auto">♡ 12K　 Share　•••</span></div><div class="description"><b>128K views · 2 days ago</b><br>A slower start, a clear mind, and time for what matters.<br>This is a deterministic browser-test fixture.</div></section><section class="recommendations">${[0,1,2,3,4,5].map(i=>card(i,true,i===2)).join('')}</section></main>`:`<aside class="nav"><div>⌂　 Home</div><div>ϟ　 Shorts</div><div>▣　 Subscriptions</div><hr><div>◷　 History</div><div>☷　 Playlists</div><div>◴　 Watch later</div></aside><main class="home"><div class="chips"><span>All</span><span>Music</span><span>Design</span><span>Mixes</span><span>Nature</span><span>Recently uploaded</span></div><section class="grid">${[0,1,2,3,4,5].map(i=>card(i,false,i===2)).join('')}</section><section class="shorts"><h2>ϟ Shorts</h2><div class="short-grid">${[0,1,2,3,4].map(i=>`<ytd-reel-item-renderer><a id="thumbnail" href="/shorts/fixture${i}"><img src="${image(i)}"></a><div id="details" class="meta details"><img class="channel-avatar" src="${image(i+1)}" alt="Everyday studio avatar"><h3><a id="video-title" href="/shorts/fixture${i}">${titles[i]}</a></h3><p class="channel-name">Everyday studio</p><p class="video-stats">24K views</p></div></ytd-reel-item-renderer>`).join('')}</div></section></main>`}<script>window.appendRecommendation=()=>{document.querySelector('.recommendations,.grid').insertAdjacentHTML('beforeend',${JSON.stringify(card(99,watch))})};window.fixtureNavigate=()=>{history.pushState({},'', '/watch?v=spa');document.dispatchEvent(new CustomEvent('yt-navigate-finish'))};</script></body></html>`; }
module.exports={html};
